const std = @import("std");

pub const Node = struct {
    id: []u8,
    type_name: []u8,
    quantum_state: std.math.Complex(f64),
    phase: f64,
    data: []u8,
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, id: []const u8, type_name: []const u8, mag: f64, phase: f64, data: []const u8) !Node {
        const norm_phase = normalizePhase(phase);
        const state = std.math.Complex(f64).init(mag * std.math.cos(norm_phase), mag * std.math.sin(norm_phase));
        return .{
            .allocator = alloc,
            .id = try alloc.dupe(u8, id),
            .type_name = try alloc.dupe(u8, type_name),
            .quantum_state = normalizeQuantumState(state),
            .phase = norm_phase,
            .data = try alloc.dupe(u8, data),
        };
    }

    pub fn deinit(self: *Node) void {
        self.allocator.free(self.id);
        self.allocator.free(self.type_name);
        self.allocator.free(self.data);
    }

    pub fn clone(self: *const Node, alloc: std.mem.Allocator) !Node {
        return try init(alloc, self.id, self.type_name, self.quantum_state.magnitude(), self.phase, self.data);
    }
};

pub const EdgeQuality = enum {
    superposition,
    entangled,
    coherent,
    collapsed,
    fractal,
};

pub const EdgeKey = struct {
    source: []u8,
    target: []u8,
};

pub const Edge = struct {
    source: []u8,
    target: []u8,
    quality: EdgeQuality,
    weight: f64,
    fractal_dimension: f64,
    quantum_correlation: std.math.Complex(f64),
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, source: []const u8, target: []const u8, quality: EdgeQuality, weight: f64, fd: f64, corr_re: f64, corr_im: f64) !Edge {
        const corr = std.math.Complex(f64).init(corr_re, corr_im);
        return .{
            .allocator = alloc,
            .source = try alloc.dupe(u8, source),
            .target = try alloc.dupe(u8, target),
            .quality = quality,
            .weight = clamp01(weight),
            .fractal_dimension = if (std.math.isFinite(fd) and fd >= 0.0) fd else 0.0,
            .quantum_correlation = normalizeQuantumState(corr),
        };
    }

    pub fn deinit(self: *Edge) void {
        self.allocator.free(self.source);
        self.allocator.free(self.target);
    }

    pub fn clone(self: *const Edge, alloc: std.mem.Allocator) !Edge {
        return try init(alloc, self.source, self.target, self.quality, self.weight, self.fractal_dimension, self.quantum_correlation.re, self.quantum_correlation.im);
    }
};

pub const SelfSimilarRelationalGraph = struct {
    allocator: std.mem.Allocator,
    nodes: std.StringHashMap(Node),
    edges: std.HashMap(EdgeKey, Edge, EdgeKeyContext, 80),
    quantum_register: std.StringHashMap(std.math.Complex(f64)),
    fractal_depth: u32,
    topology_hash: [32]u8,
    mutex: std.Thread.Mutex,

    pub const EdgeKeyContext = struct {
        pub fn hash(_: EdgeKeyContext, key: EdgeKey) u64 {
            var hasher = std.hash.Wyhash.init(0);
            hasher.update(key.source);
            hasher.update(key.target);
            return hasher.final();
        }

        pub fn eql(_: EdgeKeyContext, a: EdgeKey, b: EdgeKey, _: usize) bool {
            return std.mem.eql(u8, a.source, b.source) and std.mem.eql(u8, a.target, b.target);
        }
    };

    pub fn init(alloc: std.mem.Allocator) SelfSimilarRelationalGraph {
        return .{
            .allocator = alloc,
            .nodes = std.StringHashMap(Node).init(alloc),
            .edges = std.HashMap(EdgeKey, Edge, EdgeKeyContext, 80).init(alloc),
            .quantum_register = std.StringHashMap(std.math.Complex(f64)).init(alloc),
            .fractal_depth = 0,
            .topology_hash = std.mem.zeroes([32]u8),
            .mutex = .{},
        };
    }

    pub fn deinit(self: *SelfSimilarRelationalGraph) void {
        var node_iter = self.nodes.iterator();
        while (node_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit();
        }
        self.nodes.deinit();
        var edge_iter = self.edges.iterator();
        while (edge_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.source);
            self.allocator.free(entry.key_ptr.target);
            entry.value_ptr.deinit();
        }
        self.edges.deinit();
        var qr_iter = self.quantum_register.iterator();
        while (qr_iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.quantum_register.deinit();
    }

    pub fn addNode(self: *SelfSimilarRelationalGraph, node: Node) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        const key = try self.allocator.dupe(u8, node.id);
        errdefer self.allocator.free(key);
        if (self.nodes.contains(key)) return error.DuplicateNode;
        try self.nodes.put(key, node);
        try self.updateTopologyHash();
    }

    pub fn addEdge(self: *SelfSimilarRelationalGraph, edge: Edge) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        const key = EdgeKey{ .source = try self.allocator.dupe(u8, edge.source), .target = try self.allocator.dupe(u8, edge.target) };
        errdefer {
            self.allocator.free(key.source);
            self.allocator.free(key.target);
        }
        if (self.edges.contains(key)) return error.DuplicateEdge;
        try self.edges.put(key, edge);
        try self.updateTopologyHash();
    }

    pub fn hasNode(self: *const SelfSimilarRelationalGraph, id: []const u8) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.nodes.contains(id);
    }

    pub fn hasEdge(self: *const SelfSimilarRelationalGraph, source: []const u8, target: []const u8) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        const key = EdgeKey{ .source = @constCast(source), .target = @constCast(target) };
        return self.edges.contains(key);
    }

    pub fn getNode(self: *SelfSimilarRelationalGraph, id: []const u8) ?*Node {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.nodes.getPtr(id);
    }

    pub fn getConstNode(self: *const SelfSimilarRelationalGraph, id: []const u8) ?*const Node {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.nodes.getEntry(id)) |entry| {
            return entry.value_ptr;
        } else {
            return null;
        }
    }

    pub fn getEdge(self: *SelfSimilarRelationalGraph, source: []const u8, target: []const u8) ?*Edge {
        self.mutex.lock();
        defer self.mutex.unlock();
        const key = EdgeKey{ .source = @constCast(source), .target = @constCast(target) };
        return self.edges.getPtr(key);
    }

    pub fn getConstEdge(self: *const SelfSimilarRelationalGraph, source: []const u8, target: []const u8) ?*const Edge {
        self.mutex.lock();
        defer self.mutex.unlock();
        const key = EdgeKey{ .source = @constCast(source), .target = @constCast(target) };
        if (self.edges.getEntry(key)) |entry| {
            return entry.value_ptr;
        } else {
            return null;
        }
    }

    pub fn nodeCount(self: *const SelfSimilarRelationalGraph) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.nodes.count();
    }

    pub fn edgeCount(self: *const SelfSimilarRelationalGraph) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.edges.count();
    }

    pub fn clear(self: *SelfSimilarRelationalGraph) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.deinit();
        self.* = init(self.allocator);
    }

    pub fn setQuantumState(self: *SelfSimilarRelationalGraph, id: []const u8, state: std.math.Complex(f64)) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getNode(id)) |node| {
            node.quantum_state = normalizeQuantumState(state);
            const key = try self.allocator.dupe(u8, id);
            errdefer self.allocator.free(key);
            try self.quantum_register.put(key, node.quantum_state);
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn applyQuantumGate(self: *SelfSimilarRelationalGraph, id: []const u8, gate: fn (std.math.Complex(f64)) std.math.Complex(f64)) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getNode(id)) |node| {
            node.quantum_state = normalizeQuantumState(gate(node.quantum_state));
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn entangleNodes(self: *SelfSimilarRelationalGraph, node1: []const u8, node2: []const u8) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.hasEdge(node1, node2)) return error.DuplicateEdge;
        const edge = try Edge.init(self.allocator, node1, node2, .entangled, 1.0, 1.0, 0.0, 0.0);
        try self.addEdge(edge);
    }

    pub fn measure(self: *SelfSimilarRelationalGraph, id: []const u8) f64 {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getConstNode(id)) |node| {
            const mag = node.quantum_state.magnitude();
            var p = mag * mag;
            if (!std.math.isFinite(p)) p = 1.0;
            if (p < 0.0) p = 0.0;
            if (p > 1.0) p = 1.0;
            return p;
        }
        return 0.0;
    }

    pub fn calculateFractalDimension(self: *const SelfSimilarRelationalGraph) f64 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const n = self.nodeCount();
        const e = self.edgeCount();
        if (n <= 1 or e == 0) return 0.0;
        return std.math.log(@as(f64, @floatFromInt(e))) / std.math.log(@as(f64, @floatFromInt(n)));
    }

    pub fn getTopologyHashHex(self: *const SelfSimilarRelationalGraph) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const hash = self.topology_hash;
        var hex = try self.allocator.alloc(u8, 64);
        for (hash, 0..) |byte, i| {
            _ = std.fmt.bufPrint(hex[i * 2 .. i * 2 + 2], "{x:0>2}", .{byte}) catch unreachable;
        }
        return hex;
    }

    pub fn updateTopologyHash(self: *SelfSimilarRelationalGraph) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        var hasher = std.crypto.hash.Sha3_256.init(.{});
        var node_iter = self.nodes.iterator();
        while (node_iter.next()) |entry| {
            hasher.update(entry.key_ptr.*);
        }
        var edge_iter = self.edges.iterator();
        while (edge_iter.next()) |entry| {
            hasher.update(entry.key_ptr.source);
            hasher.update(entry.key_ptr.target);
        }
        hasher.final(&self.topology_hash);
    }

    pub fn encodeInformation(self: *SelfSimilarRelationalGraph, data: []const u8) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const hex_len = data.len * 2;
        var id = try self.allocator.alloc(u8, hex_len);
        for (data, 0..) |byte, i| {
            _ = std.fmt.bufPrint(id[i * 2 .. i * 2 + 2], "{x:0>2}", .{byte}) catch unreachable;
        }
        const node = try Node.init(self.allocator, id, "encoded", 1.0, 0.0, data);
        try self.addNode(node);
        return id;
    }

    pub fn decodeInformation(self: *const SelfSimilarRelationalGraph, alloc: std.mem.Allocator, id: []const u8) ?[]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getConstNode(id)) |node| {
            return alloc.dupe(u8, node.data) catch null;
        }
        return null;
    }
};

fn normalizePhase(phi: f64) f64 {
    if (!std.math.isFinite(phi)) return 0.0;
    const two_pi = 2.0 * std.math.pi;
    var x = std.math.fmod(phi, two_pi);
    if (x < 0.0) x += two_pi;
    return x;
}

fn clamp01(x: f64) f64 {
    if (!std.math.isFinite(x)) return 0.0;
    return std.math.clamp(x, 0.0, 1.0);
}

fn normalizeQuantumState(state: std.math.Complex(f64)) std.math.Complex(f64) {
    const mag = state.magnitude();
    if (!std.math.isFinite(mag) or mag <= 0.0) return std.math.Complex(f64).init(1.0, 0.0);
    return .{ .re = state.re / mag, .im = state.im / mag };
}

pub fn hadamardGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    const sqrt2_inv = 1.0 / std.math.sqrt(2.0);
    const re = (state.re + state.im) * sqrt2_inv;
    const im = (state.re - state.im) * sqrt2_inv;
    return std.math.Complex(f64).init(re, im);
}

pub fn pauliXGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(state.im, state.re);
}

pub fn pauliYGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(-state.im, state.re);
}

pub fn pauliZGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(state.re, -state.im);
}

pub fn identityGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return state;
}
const std = @import("std");
