pub const EdgeQuality = nsir_core.EdgeQuality;
pub const EdgeKey = nsir_core.EdgeKey;

const MAX_STRING_SCAN = 1025;
const MAX_DATA_SCAN = 1048576;
const FLOAT_EPSILON = std.math.f64_epsilon;
const EXP_UNDERFLOW_THRESHOLD = -745.0;
const DEFAULT_INITIAL_TEMP = 1.0;
const DEFAULT_COOLING_RATE = 0.95;
const DEFAULT_MAX_ITERATIONS = 1000;
const PERTURBATION_EDGE_PROBABILITY = 0.3;
const PERTURBATION_NODE_PROBABILITY = 0.2;
const PERTURBATION_EDGE_FACTOR = 0.1;
const PERTURBATION_NODE_FACTOR = 0.05;
const ACCEPTANCE_RATE_HIGH = 0.6;
const ACCEPTANCE_RATE_LOW = 0.2;
const COOLING_RATE_ADJUSTMENT_FAST = 0.98;
const COOLING_RATE_ADJUSTMENT_SLOW = 1.02;
const COOLING_RATE_MIN = 0.8;
