const VERSION_MAJOR = 4;
const VERSION_MINOR = 0;
const VERSION_PATCH = 2;

var global_gpa = std.heap.GeneralPurposeAllocator(.{ .thread_safe = true }){};
var global_gpa_inited = std.atomic.Value(bool).init(false);
