pub const OptimizationStatistics = struct {
    iterations_completed: usize,
    moves_accepted: u64,
    moves_rejected: u64,
    best_energy: f64,
    current_energy: f64,
    temperature: f64,
    acceptance_rate: f64,

    pub fn init() OptimizationStatistics {
        return .{
            .iterations_completed = 0,
            .moves_accepted = 0,
            .moves_rejected = 0,
            .best_energy = std.math.inf(f64),
            .current_energy = std.math.inf(f64),
            .temperature = 0.0,
            .acceptance_rate = 0.0,
        };
    }

    pub fn updateAcceptanceRate(self: *OptimizationStatistics) void {
        const total_moves = self.moves_accepted + self.moves_rejected;
        if (total_moves > 0) {
            self.acceptance_rate = @as(f64, @floatFromInt(self.moves_accepted)) / @as(f64, @floatFromInt(total_moves));
        } else {
            self.acceptance_rate = 0.0;
        }
    }

    pub fn incrementAccepted(self: *OptimizationStatistics) void {
        if (self.moves_accepted < std.math.maxInt(u64)) self.moves_accepted += 1;
    }

    pub fn incrementRejected(self: *OptimizationStatistics) void {
        if (self.moves_rejected < std.math.maxInt(u64)) self.moves_rejected += 1;
    }
};

pub const EntangledStochasticSymmetryOptimizer = struct {
    temperature: f64,
    cooling_rate: f64,
    max_iterations: usize,
    current_iteration: usize,
    min_temperature: f64,
    initial_temperature: f64,
    reheat_threshold: f64,
    reheat_factor: f64,
    adaptive_cooling: bool,
    prng: std.rand.DefaultPrng,
    allocator: Allocator,
    statistics: OptimizationStatistics,
    mutex: std.Thread.Mutex,

    const Self = @This();
    const DEFAULT_MIN_TEMP = 0.001;
    const DEFAULT_REHEAT_THRESHOLD = 0.1;
    const DEFAULT_REHEAT_FACTOR = 2.0;

    pub fn init(allocator: Allocator, initial_temp: f64, cooling_rate: f64, max_iterations: usize) !Self {
        var seed_bytes: [8]u8 = undefined;
        std.crypto.random.bytes(&seed_bytes);
        const seed = std.mem.readIntLittle(u64, seed_bytes[0..8]);

        const safe_initial = if (std.math.isFinite(initial_temp) and initial_temp > 0.0) initial_temp else DEFAULT_INITIAL_TEMP;
        const safe_cooling = if (std.math.isFinite(cooling_rate) and cooling_rate > 0.0 and cooling_rate < 1.0) cooling_rate else DEFAULT_COOLING_RATE;
        const safe_iters = if (max_iterations > 0) max_iterations else DEFAULT_MAX_ITERATIONS;

        return .{
            .temperature = safe_initial,
            .cooling_rate = safe_cooling,
            .max_iterations = safe_iters,
            .current_iteration = 0,
            .min_temperature = DEFAULT_MIN_TEMP,
            .initial_temperature = safe_initial,
            .reheat_threshold = DEFAULT_REHEAT_THRESHOLD,
            .reheat_factor = DEFAULT_REHEAT_FACTOR,
            .adaptive_cooling = true,
            .prng = std.rand.DefaultPrng.init(seed),
            .allocator = allocator,
            .statistics = OptimizationStatistics.init(),
            .mutex = .{},
        };
    }

    pub fn deinit(self: *Self) void {
        _ = self;
    }

    pub fn setMinTemperature(self: *Self, min_temp: f64) c_int {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (std.math.isFinite(min_temp) and min_temp > 0.0) {
            self.min_temperature = min_temp;
            return JAIDE_SUCCESS;
        }
        return JAIDE_ERROR_INVALID_PARAMETER;
    }

    pub fn setAdaptiveCooling(self: *Self, enabled: bool) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.adaptive_cooling = enabled;
    }

    pub fn setReheatParameters(self: *Self, threshold: f64, factor: f64) c_int {
        self.mutex.lock();
        defer self.mutex.unlock();
        var valid = true;
        if (std.math.isFinite(threshold) and threshold > 0.0) {
            self.reheat_threshold = threshold;
        } else {
            valid = false;
        }
        if (std.math.isFinite(factor) and factor > 0.0) {
            self.reheat_factor = factor;
        } else {
            valid = false;
        }
        return if (valid) JAIDE_SUCCESS else JAIDE_ERROR_INVALID_PARAMETER;
    }

    fn computeEnergy(graph: *const SelfSimilarRelationalGraph) f64 {
        graph.mutex.lock();
        defer graph.mutex.unlock();
        var energy: f64 = 0.0;
        var num_terms: f64 = 0.0;

        var edge_iter = graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            const edge = entry.value_ptr;
            if (std.math.isFinite(edge.weight) and std.math.isFinite(edge.fractal_dimension)) {
                const term = edge.weight * edge.fractal_dimension;
                if (std.math.isFinite(term)) {
                    energy += term;
                    num_terms += 1.0;
                }
            }
            const m = edge.quantum_correlation.magnitude();
            if (std.math.isFinite(m)) {
                energy += m;
                num_terms += 1.0;
            }
        }

        var node_iter = graph.nodes.iterator();
        while (node_iter.next()) |entry| {
            const m = entry.value_ptr.quantum_state.magnitude();
            if (std.math.isFinite(m)) {
                energy += m;
                num_terms += 1.0;
            }
        }

        if (num_terms > 0.0) energy /= num_terms;
        return energy;
    }

    fn safeCopyTopologyHash(dst: []u8, src: []const u8) void {
        const len = @min(dst.len, src.len);
        std.mem.copy(u8, dst[0..len], src[0..len]);
    }

    fn cloneGraph(self: *Self, source: *SelfSimilarRelationalGraph) !*SelfSimilarRelationalGraph {
        const new_graph = try self.allocator.create(SelfSimilarRelationalGraph);
        errdefer self.allocator.destroy(new_graph);

        new_graph.* = SelfSimilarRelationalGraph.init(self.allocator);
        errdefer new_graph.deinit();

        source.mutex.lock();
        defer source.mutex.unlock();

        var node_iter = source.nodes.iterator();
        while (node_iter.next()) |entry| {
            const cloned_node = try entry.value_ptr.clone(self.allocator);
            errdefer cloned_node.deinit();
            try new_graph.addNode(cloned_node);
        }

        var edge_iter = source.edges.iterator();
        while (edge_iter.next()) |entry| {
            const cloned_edge = try entry.value_ptr.clone(self.allocator);
            errdefer cloned_edge.deinit();
            try new_graph.addEdge(cloned_edge);
        }

        var qr_iter = source.quantum_register.iterator();
        while (qr_iter.next()) |entry| {
            const key_copy = try self.allocator.dupe(u8, entry.key_ptr.*);
            errdefer self.allocator.free(key_copy);
            try new_graph.quantum_register.put(key_copy, entry.value_ptr.*);
        }

        new_graph.fractal_depth = source.fractal_depth;
        safeCopyTopologyHash(&new_graph.topology_hash, &source.topology_hash);
        try new_graph.updateTopologyHash();

        return new_graph;
    }

    fn perturbGraph(self: *Self, graph: *SelfSimilarRelationalGraph) void {
        graph.mutex.lock();
        defer graph.mutex.unlock();

        var edge_iter = graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            var edge = entry.value_ptr;
            if (self.prng.random().float(f64) < PERTURBATION_EDGE_PROBABILITY) {
                const perturbation = (self.prng.random().float(f64) - 0.5) * self.temperature * PERTURBATION_EDGE_FACTOR;
                const w = edge.weight + perturbation;
                edge.weight = clamp01(if (std.math.isFinite(w)) w else edge.weight);
            }
        }

        var node_iter = graph.nodes.iterator();
        while (node_iter.next()) |entry| {
            if (self.prng.random().float(f64) < PERTURBATION_NODE_PROBABILITY) {
                const state = entry.value_ptr.quantum_state;
                const angle = self.prng.random().float(f64) * 2.0 * std.math.pi;
                const perturbation = self.temperature * PERTURBATION_NODE_FACTOR;
                const new_real = state.re + perturbation * std.math.cos(angle);
                const new_imag = state.im + perturbation * std.math.sin(angle);
                if (std.math.isFinite(new_real) and std.math.isFinite(new_imag)) {
                    entry.value_ptr.quantum_state = nsir_core.normalizeQuantumState(Complex.init(new_real, new_imag));
                }
            }
        }
    }

    fn acceptMove(self: *Self, delta_energy: f64) bool {
        if (!std.math.isFinite(delta_energy)) return false;
        if (delta_energy <= 0.0) return true;
        if (self.temperature <= FLOAT_EPSILON) return false;

        const x = -delta_energy / self.temperature;
        if (x < EXP_UNDERFLOW_THRESHOLD) return false;

        const acceptance_probability = std.math.exp(x);
        const random_value = self.prng.random().float(f64);
        return random_value < acceptance_probability;
    }

    fn coolTemperature(self: *Self) void {
        var adjusted_rate = self.cooling_rate;
        if (self.adaptive_cooling) {
            if (self.statistics.acceptance_rate > ACCEPTANCE_RATE_HIGH) {
                adjusted_rate *= COOLING_RATE_ADJUSTMENT_FAST;
            } else if (self.statistics.acceptance_rate < ACCEPTANCE_RATE_LOW) {
                adjusted_rate *= COOLING_RATE_ADJUSTMENT_SLOW;
            }
            adjusted_rate = std.math.clamp(adjusted_rate, COOLING_RATE_MIN, COOLING_RATE_MAX);
        }
        self.temperature *= adjusted_rate;
        if (!std.math.isFinite(self.temperature)) self.temperature = self.min_temperature;
        self.temperature = std.math.max(self.temperature, self.min_temperature);
    }

    fn copyGraphState(self: *Self, dst: *SelfSimilarRelationalGraph, src: *SelfSimilarRelationalGraph) !void {
        dst.mutex.lock();
        defer dst.mutex.unlock();
        src.mutex.lock();
        defer src.mutex.unlock();

        var tmp = SelfSimilarRelationalGraph.init(self.allocator);
        errdefer tmp.deinit();

        var node_iter = src.nodes.iterator();
        while (node_iter.next()) |entry| {
            const cloned_node = try entry.value_ptr.clone(self.allocator);
            errdefer cloned_node.deinit();
            try tmp.addNode(cloned_node);
        }

        var edge_iter = src.edges.iterator();
        while (edge_iter.next()) |entry| {
            const cloned_edge = try entry.value_ptr.clone(self.allocator);
            errdefer cloned_edge.deinit();
            try tmp.addEdge(cloned_edge);
        }

        var qr_iter = src.quantum_register.iterator();
        while (qr_iter.next()) |entry| {
            const key_copy = try self.allocator.dupe(u8, entry.key_ptr.*);
            errdefer self.allocator.free(key_copy);
            try tmp.quantum_register.put(key_copy, entry.value_ptr.*);
        }

        tmp.fractal_depth = src.fractal_depth;
        safeCopyTopologyHash(&tmp.topology_hash, &src.topology_hash);
        try tmp.updateTopologyHash();

        dst.deinit();
        dst.* = tmp;
    }

    pub fn optimize(self: *Self, graph: *SelfSimilarRelationalGraph) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        graph.mutex.lock();
        defer graph.mutex.unlock();

        self.statistics = OptimizationStatistics.init();
        self.temperature = self.initial_temperature;
        self.current_iteration = 0;

        var current_energy = computeEnergy(graph);
        var best_energy = current_energy;

        self.statistics.best_energy = best_energy;
        self.statistics.current_energy = current_energy;
        self.statistics.temperature = self.temperature;
        self.statistics.updateAcceptanceRate();

        var stagnation_counter: usize = 0;
        const stagnation_limit: usize = @max(1, self.max_iterations / 10);

        while (self.current_iteration < self.max_iterations) : (self.current_iteration += 1) {
            const candidate = try self.cloneGraph(graph);
            defer {
                candidate.deinit();
                self.allocator.destroy(candidate);
            }

            self.perturbGraph(candidate);

            const candidate_energy = computeEnergy(candidate);
            const delta_energy = candidate_energy - current_energy;

            if (self.acceptMove(delta_energy)) {
                try self.copyGraphState(graph, candidate);
                current_energy = candidate_energy;
                self.statistics.incrementAccepted();
                if (candidate_energy < best_energy) {
                    best_energy = candidate_energy;
                    self.statistics.best_energy = best_energy;
                    stagnation_counter = 0;
                } else {
                    stagnation_counter += 1;
                }
            } else {
                self.statistics.incrementRejected();
                stagnation_counter += 1;
            }

            self.statistics.current_energy = current_energy;
            self.statistics.temperature = self.temperature;
            self.statistics.iterations_completed = self.current_iteration + 1;
            self.statistics.updateAcceptanceRate();

            self.coolTemperature();

            if (stagnation_counter >= stagnation_limit) {
                const reheat_check = self.initial_temperature * self.reheat_threshold;
                if (std.math.isFinite(reheat_check) and self.temperature < reheat_check + FLOAT_EPSILON) {
                    self.temperature = std.math.max(self.min_temperature, self.temperature * self.reheat_factor);
                    stagnation_counter = 0;
                }
            }

            if (self.temperature <= self.min_temperature + FLOAT_EPSILON) break;
        }
    }
};

