const std = @import("std");

pub const Node = struct {
    id: []u8,
    type_name: []u8,
    quantum_state: std.math.Complex(f64),
    phase: f64,
    data: []u8,
    allocator: std.mem.Allocator,

    pub fn init(alloc: std.mem.Allocator, id: []const u8, type_name: []const u8, mag: f64, phase: f64, data: []const u8) !Node {
        const norm_phase = normalizePhase(phase);
        const state = std.math.Complex(f64).init(mag * std.math.cos(norm_phase), mag * std.math.sin(norm_phase));
        return .{
            .allocator = alloc,
            .id = try alloc.dupe(u8, id),
            .type_name = try alloc.dupe(u8, type_name),
            .quantum_state = normalizeQuantumState(state),
            .phase = norm_phase,
            .data = try alloc.dupe(u8, data),
        };
    }

    pub fn deinit(self: *Node) void {
        self.allocator.free(self.id);
        self.allocator.free(self.type_name);
        self.allocator.free(self.data);
    }

    pub fn clone(self: *const Node, alloc: std.mem.Allocator) !Node {
        return try init(alloc, self.id, self.type_name, self.quantum_state.magnitude(), self.phase, self.data);
    }
};

pub const EdgeQuality = enum {
    superposition,
    entangled,
    coherent,
    collapsed,
    fractal,
};

pub const EdgeKey = struct {
    source: []u8,
    target: []u8,
};

pub const Edge = struct {
    source: []u8,
    target: []u8,
