        }
    }

    pub fn nodeCount(self: *const SelfSimilarRelationalGraph) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.nodes.count();
    }

    pub fn edgeCount(self: *const SelfSimilarRelationalGraph) usize {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.edges.count();
    }

    pub fn clear(self: *SelfSimilarRelationalGraph) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.deinit();
        self.* = init(self.allocator);
    }

    pub fn setQuantumState(self: *SelfSimilarRelationalGraph, id: []const u8, state: std.math.Complex(f64)) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getNode(id)) |node| {
            node.quantum_state = normalizeQuantumState(state);
            const key = try self.allocator.dupe(u8, id);
            errdefer self.allocator.free(key);
            try self.quantum_register.put(key, node.quantum_state);
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn applyQuantumGate(self: *SelfSimilarRelationalGraph, id: []const u8, gate: fn (std.math.Complex(f64)) std.math.Complex(f64)) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getNode(id)) |node| {
            node.quantum_state = normalizeQuantumState(gate(node.quantum_state));
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn entangleNodes(self: *SelfSimilarRelationalGraph, node1: []const u8, node2: []const u8) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.hasEdge(node1, node2)) return error.DuplicateEdge;
        const edge = try Edge.init(self.allocator, node1, node2, .entangled, 1.0, 1.0, 0.0, 0.0);
        try self.addEdge(edge);
    }

    pub fn measure(self: *SelfSimilarRelationalGraph, id: []const u8) f64 {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getConstNode(id)) |node| {
            const mag = node.quantum_state.magnitude();
            var p = mag * mag;
            if (!std.math.isFinite(p)) p = 1.0;
            if (p < 0.0) p = 0.0;
            if (p > 1.0) p = 1.0;
            return p;
        }
        return 0.0;
    }

    pub fn calculateFractalDimension(self: *const SelfSimilarRelationalGraph) f64 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const n = self.nodeCount();
        const e = self.edgeCount();
        if (n <= 1 or e == 0) return 0.0;
        return std.math.log(@as(f64, @floatFromInt(e))) / std.math.log(@as(f64, @floatFromInt(n)));
    }

    pub fn getTopologyHashHex(self: *const SelfSimilarRelationalGraph) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const hash = self.topology_hash;
        var hex = try self.allocator.alloc(u8, 64);
        for (hash, 0..) |byte, i| {
            _ = std.fmt.bufPrint(hex[i * 2 .. i * 2 + 2], "{x:0>2}", .{byte}) catch unreachable;
        }
        return hex;
    }

    pub fn updateTopologyHash(self: *SelfSimilarRelationalGraph) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        var hasher = std.crypto.hash.Sha3_256.init(.{});
        var node_iter = self.nodes.iterator();
        while (node_iter.next()) |entry| {
            hasher.update(entry.key_ptr.*);
        }
        var edge_iter = self.edges.iterator();
        while (edge_iter.next()) |entry| {
            hasher.update(entry.key_ptr.source);
            hasher.update(entry.key_ptr.target);
        }
        hasher.final(&self.topology_hash);
    }

    pub fn encodeInformation(self: *SelfSimilarRelationalGraph, data: []const u8) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        const hex_len = data.len * 2;
        var id = try self.allocator.alloc(u8, hex_len);
        for (data, 0..) |byte, i| {
            _ = std.fmt.bufPrint(id[i * 2 .. i * 2 + 2], "{x:0>2}", .{byte}) catch unreachable;
        }
        const node = try Node.init(self.allocator, id, "encoded", 1.0, 0.0, data);
        try self.addNode(node);
        return id;
    }

    pub fn decodeInformation(self: *const SelfSimilarRelationalGraph, alloc: std.mem.Allocator, id: []const u8) ?[]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.getConstNode(id)) |node| {
            return alloc.dupe(u8, node.data) catch null;
        }
        return null;
    }
};

fn normalizePhase(phi: f64) f64 {
    if (!std.math.isFinite(phi)) return 0.0;
    const two_pi = 2.0 * std.math.pi;
    var x = std.math.fmod(phi, two_pi);
    if (x < 0.0) x += two_pi;
    return x;
}

fn clamp01(x: f64) f64 {
    if (!std.math.isFinite(x)) return 0.0;
    return std.math.clamp(x, 0.0, 1.0);
}

fn normalizeQuantumState(state: std.math.Complex(f64)) std.math.Complex(f64) {
    const mag = state.magnitude();
    if (!std.math.isFinite(mag) or mag <= 0.0) return std.math.Complex(f64).init(1.0, 0.0);
    return .{ .re = state.re / mag, .im = state.im / mag };
}

pub fn hadamardGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    const sqrt2_inv = 1.0 / std.math.sqrt(2.0);
    const re = (state.re + state.im) * sqrt2_inv;
    const im = (state.re - state.im) * sqrt2_inv;
    return std.math.Complex(f64).init(re, im);
}

pub fn pauliXGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(state.im, state.re);
}

pub fn pauliYGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(-state.im, state.re);
}

pub fn pauliZGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return std.math.Complex(f64).init(state.re, -state.im);
}

pub fn identityGate(state: std.math.Complex(f64)) std.math.Complex(f64) {
    return state;
}
