pub export fn jaide_add_node(graph: ?*CGraph, id: [*c]const u8, type_name: [*c]const u8) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    const id_slice = cStringToNonEmptySliceMax(id, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    if (id_slice.len > MAX_STRING_SCAN - 1) return JAIDE_ERROR_INVALID_PARAMETER;
    const type_slice = cStringToSliceMax(type_name, MAX_STRING_SCAN) orelse "";
    const internal = graph.?.toInternal();
    if (internal.hasNode(id_slice)) return JAIDE_ERROR_DUPLICATE_NODE;
    const node = Node.init(internal.allocator, id_slice, type_slice, 1.0, 0.0, "") catch |e| {
        if (e == error.OutOfMemory) return JAIDE_ERROR_ALLOCATION;
        return JAIDE_ERROR_OPERATION_FAILED;
    };
    internal.addNode(node) catch |e| {
        node.deinit();
        if (e == error.OutOfMemory) return JAIDE_ERROR_ALLOCATION;
        return JAIDE_ERROR_OPERATION_FAILED;
    };
    return JAIDE_SUCCESS;
}

pub export fn jaide_remove_node(graph: ?*CGraph, id: [*c]const u8) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    const id_slice = cStringToNonEmptySliceMax(id, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    const internal = graph.?.toInternal();
    if (!internal.hasNode(id_slice)) return JAIDE_ERROR_NODE_NOT_FOUND;

    internal.mutex.lock();
    defer internal.mutex.unlock();

    var edges_to_remove = ArrayList(EdgeKey).init(internal.allocator);
    defer edges_to_remove.deinit();

    var edge_iter = internal.edges.iterator();
    while (edge_iter.next()) |entry| {
        const key = entry.key_ptr.*;
        if (std.mem.eql(u8, key.source, id_slice) or std.mem.eql(u8, key.target, id_slice)) {
            edges_to_remove.append(key) catch return JAIDE_ERROR_ALLOCATION;
        }
    }

    for (edges_to_remove.items) |key| {
        if (internal.edges.fetchRemove(key)) |removed| {
            internal.allocator.free(removed.key.source);
            internal.allocator.free(removed.key.target);
            removed.value.deinit();
        }
    }

    if (internal.nodes.fetchRemove(id_slice)) |removed| {
        internal.allocator.free(removed.key);
        removed.value.deinit();
    }

    if (internal.quantum_register.fetchRemove(id_slice)) |removed| {
        internal.allocator.free(removed.key);
    }

    internal.updateTopologyHash() catch return JAIDE_ERROR_OPERATION_FAILED;

    return JAIDE_SUCCESS;
}

pub export fn jaide_get_node_quantum_state(graph: ?*CGraph, id: [*c]const u8, out_state: ?*CQuantumState) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (out_state == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    const id_slice = cStringToNonEmptySliceMax(id, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    const internal = graph.?.toInternal();
    if ((internal.getConstNode(id_slice)) == null) return JAIDE_ERROR_NODE_NOT_FOUND;
    const node = internal.getConstNode(id_slice).?;
    out_state.?.real = node.quantum_state.re;
    out_state.?.imag = node.quantum_state.im;
    return JAIDE_SUCCESS;
}

pub export fn jaide_set_node_quantum_state(graph: ?*CGraph, id: [*c]const u8, real: f64, imag: f64) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    if (!std.math.isFinite(real) or !std.math.isFinite(imag)) return JAIDE_ERROR_INVALID_PARAMETER;
    const id_slice = cStringToNonEmptySliceMax(id, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    const internal = graph.?.toInternal();
    internal.setQuantumState(id_slice, Complex.init(real, imag)) catch |e| {
        if (e == error.NodeNotFound) return JAIDE_ERROR_NODE_NOT_FOUND;
        if (e == error.OutOfMemory) return JAIDE_ERROR_ALLOCATION;
        return JAIDE_ERROR_OPERATION_FAILED;
    };
    return JAIDE_SUCCESS;
}

pub export fn jaide_add_edge(graph: ?*CGraph, source: [*c]const u8, target: [*c]const u8, weight: f64) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    const source_slice = cStringToNonEmptySliceMax(source, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    if (source_slice.len > MAX_STRING_SCAN - 1) return JAIDE_ERROR_INVALID_PARAMETER;
    const target_slice = cStringToNonEmptySliceMax(target, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    if (target_slice.len > MAX_STRING_SCAN - 1) return JAIDE_ERROR_INVALID_PARAMETER;
    if (std.mem.eql(u8, source_slice, target_slice)) return JAIDE_ERROR_SELF_REFERENCE;
    const internal = graph.?.toInternal();
    if (!internal.hasNode(source_slice)) return JAIDE_ERROR_NODE_NOT_FOUND;
    if (!internal.hasNode(target_slice)) return JAIDE_ERROR_NODE_NOT_FOUND;
    const w = clamp01(weight);
    const edge = Edge.init(internal.allocator, source_slice, target_slice, .coherent, w, 1.0, 0.0, 1.0) catch |e| {
        if (e == error.OutOfMemory) return JAIDE_ERROR_ALLOCATION;
        return JAIDE_ERROR_OPERATION_FAILED;
    };
    internal.addEdge(edge) catch |e| {
        edge.deinit();
        if (e == error.DuplicateEdge) return JAIDE_ERROR_DUPLICATE_EDGE;
        if (e == error.OutOfMemory) return JAIDE_ERROR_ALLOCATION;
        return JAIDE_ERROR_OPERATION_FAILED;
    };
    return JAIDE_SUCCESS;
}

pub export fn jaide_remove_edge(graph: ?*CGraph, source: [*c]const u8, target: [*c]const u8) c_int {
    if (graph == null) return JAIDE_ERROR_NULL_POINTER;
    if (!global_gpa_inited.load(.acquire)) return JAIDE_ERROR_NOT_INITIALIZED;
    const source_slice = cStringToNonEmptySliceMax(source, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    const target_slice = cStringToNonEmptySliceMax(target, MAX_STRING_SCAN) orelse return JAIDE_ERROR_INVALID_STRING;
    const internal = graph.?.toInternal();
    internal.mutex.lock();
    defer internal.mutex.unlock();
    const key = EdgeKey{ .source = @constCast(source_slice), .target = @constCast(target_slice) };
    if (internal.edges.fetchRemove(key)) |removed| {
        internal.allocator.free(removed.key.source);
        internal.allocator.free(removed.key.target);
        removed.value.deinit();
        internal.updateTopologyHash() catch return JAIDE_ERROR_OPERATION_FAILED;
        return JAIDE_SUCCESS;
    }
    return JAIDE_ERROR_EDGE_NOT_FOUND;
}

pub export fn jaide_get_edge_weight(graph: ?*CGraph, source: [*c]const u8, target: [*c]const u8) f64 {
    if (graph == null) return -1.0;
    if (!global_gpa_inited.load(.acquire)) return -1.0;
    const source_slice = cStringToNonEmptySliceMax(source, MAX_STRING_SCAN) orelse return -1.0;
    const target_slice = cStringToNonEmptySliceMax(target, MAX_STRING_SCAN) orelse return -1.0;
    const internal = graph.?.toInternalConst();
    if ((internal.getConstEdge(source_slice, target_slice)) == null) return -1.0;
    const edge = internal.getConstEdge(source_slice, target_slice).?;
    const w = edge.weight;
    if (!std.math.isFinite(w)) return -1.0;
    return w;
}

